public static function randomString($max = 16) {

  $bank = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  $bank .= 'abcdefghijklmnopqrstuvwxyz';
  $bank .= '0123456789';

  $str = str_shuffle($bank);

  while (is_numeric($str[0])) {
    $str = str_shuffle($bank);
  }

  $str = substr($str, 0, $max);

  return $str;

}

