// Human size from bytes
public static function humanSize($bytes) {
  if (is_int($bytes)) {
    $label = ['B', 'KB', 'MB', 'GB', 'TB', 'PB'];
    for ($i = 0; $bytes >= 1024 && $i < (count($label) - 1); $bytes /= 1024, $i++);

    return (round($bytes, 2) . " " . $label[$i]);
  } else return $bytes;
}

